[ClaudeCode/시스템 AI] tool_use mcp__indiebizos__execute_ibl {"code": "#!ibl edition=2
[def:처리]($job) {
  [if:$job.접수 != "성공"] { return {agent_id:$job.agent_id, 접수:$job.접수, 결과:"접수 실패", 사유:get($job,"사유")} }
  $w = [try] {
    $r = [self:task]{op:"wait", ref:$job.task_ref, timeout:15}
    return {kind:"value", state:$r.state, timed_out:$r.timed_out, result:$r.result}
  } [catch] {
    return {kind:"error", state:get($error.details,"state"), failure:get($error.details,"failure"), message:$error.message}
  }
  [if:$w.kind == "value" and $w.state == "succeeded"] {
    return {agent_id:$job.agent_id, 접수:"성공", 대기:"15초 안에 완료", state:"succeeded", 요약:$w.result, task_ref:$job.task_ref}
  }
  [if:$w.kind == "error"] {
    return {agent_id:$job.agent_id, 접수:"성공", 대기:"작업이 실패·취소·유실로 종료", state:$w.state, failure:$w.failure, 상태:"이미 끝남", task_ref:$job.task_ref}
  }
  $c = [try] {
    $x = [self:task]{op:"cancel", ref:$job.task_ref}
    $cat = $x.state == "cancelled" ? "취소됨" : ($x.state == "cancel_requested" ? "취소 요청됨" : ($x.terminal ? "이미 끝남" : "취소 불가(계속 실행 중)"))
    return {state:$x.state, 상태:$cat, result:$x.result, 거절:null}
  } [catch] {
    return {state:get($error.details,"state"), 상태:"취소 불가(계속 실행 중)", result:null, 거절:$error.message}
  }
  return {agent_id:$job.agent_id, 접수:"성공", 대기:"15초 시간 초과", 대기_state:$w.state, cancel_state:$c.state, 상태:$c.상태, 요약:$c.result, cancel_거절:$c.거절, task_ref:$job.task_ref}
}
